def plasma(t):
    for row in range(ROWS):
        for col in range(COLS):
            x, y = col / 6, row / 3
            v = (math.sin(x + t) + math.sin(y + t * 1.3) + math.sin((x + y + t) / 2)
                 + math.sin(math.hypot(x - 8, y - 7) - t * 2))
            yield shade((v + 4) / 8)   # -4..4 → 0..1 → one of 12 characters
